import java.io.InputStream
import java.util.InputMismatchException
import java.util.Comparator

class InputReader(private val stream: InputStream) {
    private val buf = ByteArray(8192)
    private var curChar = 0
    private var snumChars = 0

    fun read(): Int {
        if (snumChars == -1)
            throw InputMismatchException()
        if (curChar >= snumChars) {
            curChar = 0
            try {
                snumChars = stream.read(buf)
            } catch (e: IOException) {
                throw InputMismatchException()
            }
            if (snumChars <= 0)
                return -1
        }
        return buf[curChar++].toInt()
    }

    fun nextInt(): Int {
        var c = read()
        while (isSpaceChar(c)) {
            c = read()
        }
        var sgn = 1
        if (c == '-') {
            sgn = -1
            c = read()
        }
        var res = 0
        do {
            res *= 10
            res += c - '0'
            c = read()
        } while (!isSpaceChar(c))
        return res * sgn
    }

    fun nextLong(): Long {
        var c = read()
        while (isSpaceChar(c)) {
            c = read()
        }
        var sgn = 1L
        if (c == '-') {
            sgn = -1
            c = read()
        }
        var res = 0L
        do {
            res *= 10
            res += (c - '0').toLong()
            c = read()
        } while (!isSpaceChar(c))
        return res * sgn
    }

    fun nextIntArray(n: Int): IntArray {
        val a = IntArray(n)
        for (i in 0 until n) {
            a[i] = nextInt()
        }
        return a
    }

    fun readString(): String {
        var c = read()
        while (isSpaceChar(c)) {
            c = read()
        }
        val res = StringBuilder()
        do {
            res.appendCodePoint(c)
            c = read()
        } while (!isSpaceChar(c))
        return res.toString()
    }

    fun nextLine(): String {
        var c = read()
        while (isSpaceChar(c))
            c = read()
        val res = StringBuilder()
        do {
            res.appendCodePoint(c)
            c = read()
        } while (!isEndOfLine(c))
        return res.toString()
    }

    private fun isSpaceChar(c: Int): Boolean {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1
    }

    private fun isEndOfLine(c: Int): Boolean {
        return c == '\n' || c == '\r' || c == -1
    }
}

